const clock = value => Number.isSafeInteger(value) && value >= 0;

// The owned fixture sends answer, progress and Player state in three ordered
// notifications. Freeze the unchanged-state baseline only after all three have
// persisted. Later retention assertions still compare the exact envelope.
export function matchesMergedReturnBaseline(raw, answer) {
  try {
    const state = JSON.parse(raw);
    const unit = state.unitState, player = state.playerState, times = state.fieldTimestamps;
    const answerAt = times?.dataParts?.answer;
    const progressAt = times?.unitState?.responseProgress;
    const presentationAt = times?.unitState?.presentationProgress;
    const pageAt = times?.playerState?.currentPage;
    const pagesAt = times?.playerState?.validPages;
    return state.kind === 'verona_unit_state' && state.version === 1 &&
      unit?.dataParts?.answer === answer && unit.unitStateDataType === 'verona-smoke@1' &&
      state.dataPartValueTypes?.answer === 'string' &&
      unit.presentationProgress === 'complete' && unit.responseProgress === 'complete' &&
      player?.currentPage === 'page-1' && Array.isArray(player.validPages) && player.validPages.length === 2 &&
      player.validPages[0]?.id === 'page-1' && player.validPages[0]?.label === 'Introduction' &&
      player.validPages[1]?.id === 'page-2' && player.validPages[1]?.label === 'Review' &&
      [answerAt, progressAt, presentationAt, pageAt, pagesAt].every(clock) &&
      progressAt >= answerAt && presentationAt >= answerAt &&
      pageAt >= Math.max(progressAt, presentationAt) && pagesAt >= Math.max(progressAt, presentationAt);
  } catch {return false;}
}
import {raceWithSmokeDeadline} from './smoke-deadline.mjs';

// The deadline includes receiving the entire response body, not only headers.
export async function readNativeSmokeResponse(url, init = {}, {timeoutMs = 20_000, fetchImpl = fetch} = {}) {
  const controller = new AbortController();
  const failure = Error('Owned native request timed out.');
  const signal = init.signal ? AbortSignal.any([init.signal, controller.signal]) : controller.signal;
  const response = (async () => {
    const result = await fetchImpl(url, {...init, signal});
    const text = await result.text();
    return {ok: result.ok, status: result.status, text};
  })();
  return raceWithSmokeDeadline(response, timeoutMs, () => {
    controller.abort(failure);
    throw failure;
  });
}

export async function stopNativeSmokeServer(child, {timeoutMs = 10_000, killGraceMs = 2_000} = {}) {
  if (child.exitCode !== null || child.signalCode !== null) return;
  let onClose, onError;
  const closed = new Promise((done, reject) => {
    onClose = done; onError = reject;
    child.once('close', onClose); child.once('error', onError);
  });
  let timedOut = false;
  const failure = Error('Owned native server shutdown timed out.');
  try {
    child.kill('SIGTERM');
    await raceWithSmokeDeadline(closed, timeoutMs, async () => {
      timedOut = true;
      child.kill('SIGKILL');
      await raceWithSmokeDeadline(closed, killGraceMs, () => {throw failure;});
    });
    if (timedOut) throw failure;
  } finally {
    child.removeListener('close', onClose); child.removeListener('error', onError);
  }
}

// The API subprocess must release inherited pipes when its test owner dies.
// Its IPC lease is independent of a parent finally block or supervisor timer.
export function bindNativeSmokeServerOwner(server, {owner = process, graceMs = 2_000} = {}) {
  if (!Number.isSafeInteger(graceMs) || graceMs <= 0) throw Error('Owned native server grace must be finite and positive.');
  let stopping = false;
  const stop = () => {
    if (stopping) return;
    stopping = true;
    const deadline = setTimeout(() => owner.exit(1), graceMs);
    try {
      server.closeAllConnections();
      server.close(() => {clearTimeout(deadline); owner.exit(0);});
    } catch {
      clearTimeout(deadline); owner.exit(1);
    }
  };
